 * Lexer for the tiny language described in the task. Scans a full source
 * string (already decoded as UTF-8 text) into a list of tokens, or throws a
 * ScanError describing the first problem encountered.
 */

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isIdentStart = (c) => c !== undefined && /[A-Za-z_]/.test(c)
const isIdentCont = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c)
const isDecDigit = (c) => c !== undefined && /[0-9]/.test(c)
const isHexDigit = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c !== undefined && /[01]/.test(c)
const isOctDigit = (c) => c !== undefined && /[0-7]/.test(c)
const isWhitespace = (c) => c === ' ' || c === '\t' || c === '\r' || c === '\n'

class Cursor {
  constructor(text) {
    this.cps = Array.from(text)
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  atEnd() {
    return this.pos >= this.cps.length
  }

  peek(offset = 0) {
    return this.cps[this.pos + offset]
  }

  advance() {
    const c = this.cps[this.pos]
    this.pos += 1
    if (c === '\n') {
      this.line += 1
      this.col = 1
    } else if (c === '\t') {
      const zero = this.col - 1
      const next = (Math.floor(zero / 4) + 1) * 4
      this.col = next + 1
    } else {
      this.col += 1
    }
    return c
  }
}

function consumeDigitRun(cur, isDigit) {
  if (!isDigit(cur.peek())) return ''
  let s = cur.advance()
  for (;;) {
    if (isDigit(cur.peek())) {
      s += cur.advance()
    } else if (cur.peek() === '_' && isDigit(cur.peek(1))) {
      s += cur.advance()
      s += cur.advance()
    } else {
      break
    }
  }
  return s
}

function consumeGarbage(cur) {
  let s = ''
  while (isIdentCont(cur.peek())) s += cur.advance()
  return s
}

function parseNumber(cur) {
  const line = cur.line
  const col = cur.col
  let text = ''

  const c0 = cur.peek()
  const c1 = cur.peek(1)
  if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
    text += cur.advance()
    text += cur.advance()
    const run = consumeDigitRun(cur, isHexDigit)
    if (run === '') {
      const garbage = consumeGarbage(cur)
      throw new ScanError(line, col, `invalid number ${text}${garbage}`)
    }
    text += run
  } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
    text += cur.advance()
    text += cur.advance()
    const run = consumeDigitRun(cur, isBinDigit)
    if (run === '') {
      const garbage = consumeGarbage(cur)
      throw new ScanError(line, col, `invalid number ${text}${garbage}`)
    }
    text += run
  } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
    text += cur.advance()
    text += cur.advance()
    const run = consumeDigitRun(cur, isOctDigit)
    if (run === '') {
      const garbage = consumeGarbage(cur)
      throw new ScanError(line, col, `invalid number ${text}${garbage}`)
    }
    text += run
  } else {
    text += consumeDigitRun(cur, isDecDigit)
    if (cur.peek() === '.' && isDecDigit(cur.peek(1))) {
      text += cur.advance()
      text += consumeDigitRun(cur, isDecDigit)
    }
    if (cur.peek() === 'e' || cur.peek() === 'E') {
      const n1 = cur.peek(1)
      const n2 = cur.peek(2)
      const exponentFollows =
        isDecDigit(n1) || ((n1 === '+' || n1 === '-') && isDecDigit(n2))
      if (exponentFollows) {
        text += cur.advance()
        if (cur.peek() === '+' || cur.peek() === '-') text += cur.advance()
        text += consumeDigitRun(cur, isDecDigit)
      }
    }
  }

  if (isIdentCont(cur.peek())) {
    const garbage = consumeGarbage(cur)
    throw new ScanError(line, col, `invalid number ${text}${garbage}`)
