function parseString(cur) {
  const line = cur.line
  const col = cur.col
  cur.advance() // opening quote
  let value = ''
  for (;;) {
    if (cur.atEnd()) throw new ScanError(line, col, 'unterminated string')
    const c = cur.peek()
    if (c === '"') {
      cur.advance()
      break
    }
    if (c === '\n') {
      throw new ScanError(cur.line, cur.col, 'newline in string')
    }
    if (c === '\\') {
      const bsLine = cur.line
      const bsCol = cur.col
      cur.advance() // backslash
      if (cur.atEnd()) throw new ScanError(line, col, 'unterminated string')
      const e = cur.peek()
