        value += '\n'
        cur.advance()
      } else if (e === 't') {
        value += '\t'
        cur.advance()
      } else if (e === 'r') {
        value += '\r'
        cur.advance()
      } else if (e === '\\') {
        value += '\\'
        cur.advance()
      } else if (e === '"') {
        value += '"'
        cur.advance()
      } else if (e === '0') {
        value += '\0'
        cur.advance()
      } else if (e === 'x') {
        const h1 = cur.peek(1)
        const h2 = cur.peek(2)
