          cur.advance() // x
          cur.advance() // h1
          cur.advance() // h2
          value += String.fromCharCode(parseInt(h1 + h2, 16))
        } else {
          throw new ScanError(bsLine, bsCol, 'invalid escape \\x')
        }
      } else if (e === 'u') {
        if (cur.peek(1) === '{') {
          let i = 2
          let hex = ''
          while (isHexDigit(cur.peek(i))) {
            hex += cur.peek(i)
            i += 1
          }
          if (hex.length > 0 && cur.peek(i) === '}') {
            const codepoint = parseInt(hex, 16)
            if (codepoint <= 0x10ffff) {
              for (let k = 0; k <= i; k += 1) cur.advance()
              value += String.fromCodePoint(codepoint)
            } else {
              throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
            }
          } else {
            throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
          }
        } else {
          throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
        }
      } else {
        throw new ScanError(bsLine, bsCol, `invalid escape \\${e}`)
      }
    } else {
      value += cur.advance()
    }
  }
  return { kind: 'string', line, col, text: value }
}

function parseRawString(cur) {
  const line = cur.line
  const col = cur.col
  cur.advance() // r
  cur.advance() // opening quote
  let value = ''
  for (;;) {
    if (cur.atEnd()) throw new ScanError(line, col, 'unterminated string')
    const c = cur.peek()
    if (c === '"') {
      cur.advance()
      break
    }
    value += cur.advance()
  }
  return { kind: 'rawstring', line, col, text: value }
}

function parseBlockComment(cur) {
  const line = cur.line
  const col = cur.col
  cur.advance() // /
  cur.advance() // *
  let depth = 1
  while (depth > 0) {
    if (cur.atEnd()) throw new ScanError(line, col, 'unterminated block comment')
    if (cur.peek() === '/' && cur.peek(1) === '*') {
      cur.advance()
      cur.advance()
      depth += 1
    } else if (cur.peek() === '*' && cur.peek(1) === '/') {
      cur.advance()
      cur.advance()
      depth -= 1
    } else {
      cur.advance()
    }
  }
}

function parseLineComment(cur) {
  cur.advance() // /
  cur.advance() // /
  while (!cur.atEnd() && cur.peek() !== '\n') cur.advance()
}

function parsePunct(cur) {
  const line = cur.line
  const col = cur.col
  const two = (cur.peek() ?? '') + (cur.peek(1) ?? '')
  if (TWO_CHAR_PUNCT.has(two)) {
    cur.advance()
    cur.advance()
    return { kind: 'punct', line, col, text: two }
  }
  const one = cur.peek()
  if (ONE_CHAR_PUNCT.has(one)) {
    cur.advance()
    return { kind: 'punct', line, col, text: one }
  }
  throw new ScanError(line, col, `unexpected character ${one}`)
}

export function scan(text) {
  const cur = new Cursor(text)
  const tokens = []

  for (;;) {
    for (;;) {
      let progressed = false
      while (!cur.atEnd() && isWhitespace(cur.peek())) {
        cur.advance()
        progressed = true
      }
      if (!cur.atEnd() && cur.peek() === '/' && cur.peek(1) === '/') {
        parseLineComment(cur)
        progressed = true
      } else if (!cur.atEnd() && cur.peek() === '/' && cur.peek(1) === '*') {
        parseBlockComment(cur)
        progressed = true
      }
      if (!progressed) break
    }

    if (cur.atEnd()) break

    const c = cur.peek()
    const c1 = cur.peek(1)
    let token
    if (c === 'r' && c1 === '"') {
      token = parseRawString(cur)
    } else if (c === '"') {
      token = parseString(cur)
    } else if (isIdentStart(c)) {
      token = parseIdent(cur)
    } else if (isDecDigit(c)) {
      token = parseNumber(cur)
    } else {
      token = parsePunct(cur)
    }
    tokens.push(token)
  }

  return tokens
}
