/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import fs from 'node:fs'
import { scan, ScanError } from './scanner.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  let source
  try {
    source = fs.readFileSync(0, 'utf8')
  } catch {
    source = ''
  }

  let tokens
  try {
    tokens = scan(source)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  if (mode === 'tokens') {
    let out = ''
    for (const t of tokens) {
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.text) : t.text
      out += `${t.line}:${t.col} ${t.kind} ${body}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind] += 1
    let out = ''
    for (const k of STAT_KINDS) out += `${k} ${counts[k]}\n`
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }

  process.exit(0)
}

main()
